B.ban=new A.aB("sfx_t14_lamp_flicker",0.001,1,null,1)
B.afu=s([B.ban],t.e)
B.boe=new A.h9("N\u011bkdy se mus\xed\u0161 o kousek vr\xe1tit, a\u0165 se dostane\u0161 d\xe1l.","P\u0159elij ze zvednut\xe9 n\xe1doby do t\xe9, kter\xe1 sv\xedt\xed. Cesta dop\u0159edu n\u011bkdy vede kousek zp\xe1tky.")
B.afv=s([B.boe],t.AE)
B.a3j=new A.k(0.7019607843137254,1,0.8784313725490196,0.5490196078431373,B.d)
B.a3g=new A.k(0.25098039215686274,1,0.8784313725490196,0.5490196078431373,B.d)
B.a_8=new A.k(0,1,0.8784313725490196,0.5490196078431373,B.d)
B.afw=s([B.a3j,B.a3g,B.a_8],t.W)
B.awV=new A.aO("Je \u010dtvrtek odpoledne a t\u0159\xedda je na v\xfdlet\u011b v muzeu. Vstupn\xed hala je pln\xe1 d\u011bt\xed. Dupou po schodech, \u0161eptaj\xed si a sm\u011bj\xed se. Ema, Jon\xe1\u0161, Nela a ty se zastav\xedte u velk\xe9ho obrazu u hlavn\xedch dve\u0159\xed. Je na n\u011bm vzne\u0161en\xe1 d\xe1ma v \u0161atech, kter\xe1 sp\xed. A tv\xe1\u0159\xed se p\u011bkn\u011b nerudn\u011b.")
B.aM=new A.ki("ema","assets/images/stories/museum/story/portrait_ema.webp")
B.ahl=s(["\u201e\u201aBaronka Frida von\u2026 Schla\u2026 Scho\u2026 Schovanburger.\u2018 Schovan\xfd burger? Kter\xfd bl\xe1zen by schov\xe1val burger?\u201c"],t.s)
B.biN=new A.a6(B.aM,B.ahl,!1)
B.aS=new A.ki("jonas","assets/images/stories/museum/story/portrait_jonas.webp")
B.agA=s(["\u201eSchlafenberg, Emo. \u017d\xe1dn\xfd schovan\xfd burger. Schlafen je n\u011bmecky sp\xe1t a Berg je hora. Kdy\u017e si to p\u0159elo\u017e\xed\u0161, tak je to Baronka ze Spac\xed hory.\u201c"],t.s)
B.bjb=new A.a6(B.aS,B.agA,!1)
B.aZ=new A.ki("nela","assets/images/stories/museum/story/portrait_nela.webp")
B.anA=s(["\u201eTak to se na t\xe9 ho\u0159e asi moc dob\u0159e nesp\xed. Vypad\xe1, \u017ee nespala celou v\u011b\u010dnost.\u201c"],t.s)
B.bjM=new A.a6(B.aZ,B.anA,!1)
B.axi=new A.aO("Pod jm\xe9nem baronky vis\xed je\u0161t\u011b jedna men\u0161\xed cedulka.")
B.ae0=s(["\u201e\u201aZ\xedtra r\xe1no se obraz st\u011bhuje do nov\xe9 galerie na hlavn\xedm n\xe1dra\u017e\xed.\u2018\u201c"],t.s)
B.blc=new A.a6(B.aM,B.ae0,!1)
B.axj=new A.aO("Jon\xe1\u0161 by p\u0159\xedsahal, \u017ee se baronka v tu chv\xedli zamra\u010dila je\u0161t\u011b v\xedc.")
B.aoh=s([B.awV,B.biN,B.bjb,B.bjM,B.axi,B.blc,B.axj],t.a)
B.bmQ=new A.cl("story_01",B.aoh)
B.awv=new A.aO("Kdy\u017e exkurze skon\u010d\xed, v\u0161ichni sp\u011bchaj\xed k autobusu. Teda t\xe9m\u011b\u0159 v\u0161ichni.")
B.ahT=s(["\u201ePsst. M\xe1m pl\xe1n. Schov\xe1me se v \u0161atn\u011b a muzeum bude v noci jen na\u0161e.\u201c"],t.s)
B.biu=new A.a6(B.aM,B.ahT,!1)
B.ag4=s(["\u201eTo je ten nejhor\u0161\xed pl\xe1n, jak\xfd jsem kdy sly\u0161el.\u201c"],t.s)
B.bit=new A.a6(B.aS,B.ag4,!1)
B.awh=new A.aO("Autobus odjede. Muzeum se zav\u0159e a sv\u011btla zhasnou. V\u0161echny hodiny v muzeu se v tu chv\xedli zastav\xed a ru\u010di\u010dky sko\u010d\xed na p\u016flnoc.")
B.anG=s(["\u201eZavol\xe1m dom\u016f, \u017ee se exkurze trochu prot\xe1hne. Hm. Nem\xe1m sign\xe1l, ani \u010d\xe1rku.\u201c"],t.s)
B.bk6=new A.a6(B.aZ,B.anG,!1)
B.agw=s(["\u201eA vstupn\xed dve\u0159e jsou zam\u010den\xe9! Jako by n\xe1s muzeum necht\u011blo pustit ven.\u201c"],t.s)
B.bim=new A.a6(B.aS,B.agw,!1)
B.awn=new A.aO("A d\u011bti poprv\xe9 napadne, \u017ee se odsud mo\u017en\xe1 nedostanou. Ani dnes. Ani nikdy.")
B.abr=s(["\u201eTak nebudeme \u010dekat. Prozkoum\xe1me to tu. Jenom pot\u0159ebujeme sv\u011btlo.\u201c"],t.s)
B.blC=new A.a6(B.aM,B.abr,!1)
B.awt=new A.aO("V muzeu je prapodivn\xe9 ticho. V \u0161atn\u011b na zdi nejist\u011b blik\xe1 lampa. Nela najde u dve\u0159\xed star\xfd oto\u010dn\xfd vyp\xedna\u010d a zku\u0161en\u011b s n\xedm p\xe1rkr\xe1t cvakne. Lampa zaprask\xe1, zablik\xe1 a rozsv\xedt\xed se naplno.")
B.afM=s([B.awv,B.biu,B.bit,B.awh,B.bk6,B.bim,B.awn,B.blC,B.awt],t.a)
B.bmJ=new A.cl("story_02",B.afM)
B.awX=new A.aO("Posledn\xed sk\u0159\xed\u0148ka se s vrznut\xedm otev\u0159e a na zem vypadne sto\u010den\xfd svitek. Je to pl\xe1nek muzea, nakreslen\xfd rukou. Na druh\xe9 stran\u011b je n\u011bco naps\xe1no rozt\u0159esen\xfdm p\xedsmem.")
B.afc=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d. Nev\u011b\u0159te jej\xedmu \xfasm\u011bvu. V. T.\u2018\u201c"],t.s)
B.bla=new A.a6(B.aS,B.afc,!1)
B.akW=s(["\u201eKdo je V. T.? A jak\xe9mu \xfasm\u011bvu?\u201c"],t.s)
B.bje=new A.a6(B.aM,B.akW,!1)
B.amQ=s(["\u201eSuper. Jsme zam\u010den\xed v muzeu a dost\xe1v\xe1me podivn\xe9 vzkazy. U\u017e tu chyb\xed jen stra\u0161idlo.\u201c"],t.s)
B.bl5=new A.a6(B.aZ,B.amQ,!1)
B.awj=new A.aO("Z chodby se ozve tich\xe9 \u0161ust\u011bn\xed dlouh\xfdch sukn\xed. A pak ospal\xfd \u0161epot, tak tich\xfd, \u017ee to mohl b\xfdt i pr\u016fvan:")
B.xd=new A.ki("baroness","assets/images/stories/museum/story/portrait_baroness.webp")
B.aoU=s(["\u201eRuhe\u2026\u201c"],t.s)
B.bj0=new A.a6(B.xd,B.aoU,!0)
B.agv=s(["\u201eTo je n\u011bmecky. Znamen\xe1 to\u2026 ticho.\u201c"],t.s)
B.blT=new A.a6(B.aS,B.agv,!1)
B.ax8=new A.aO("V\u0161em se zatajuje dech, proto\u017ee ta chodba je pr\xe1zdn\xe1.")
B.ax9=new A.aO("D\u011bti rychle rozlo\u017e\xed pl\xe1nek na podlaze. Jen\u017ee tma na pap\xed\u0159e se pohne. P\u0159es chodby a s\xe1ly se pomalu val\xed \u010dern\xe1 mlha a schov\xe1v\xe1 cestu. Vid\u011bt je jen \u0161atna, kde pr\xe1v\u011b stoj\xed.")
B.aq2=s(["\u201eK \u010demu n\xe1m je zaml\u017een\xfd pl\xe1nek? Co s t\xedm chcete d\u011blat? Hr\xe1t na schov\xe1vanou?\u201c"],t.s)
B.bkY=new A.a6(B.aZ,B.aq2,!1)
B.ajX=s(["\u201eTen pl\xe1nek n\xe1s n\u011bkam vede. Tak jdeme zjistit kam.\u201c"],t.s)
B.bjp=new A.a6(B.aM,B.ajX,!1)
B.al8=s(["\u201eEmo, po\u010dkej\u2026 Emo!\u201c"],t.s)
B.bk9=new A.a6(B.aS,B.al8,!1)
B.aoP=s([B.awX,B.bla,B.bje,B.bl5,B.awj,B.bj0,B.blT,B.ax8,B.ax9,B.bkY,B.bjp,B.bk9],t.a)
B.bmX=new A.cl("story_03",B.aoP)
B.axL=new A.aO("Posledn\xed dve\u0159e se otev\u0159ou a na pl\xe1nku se rozz\xe1\u0159\xed nakreslen\xe1 kost. D\u011bti stoj\xed p\u0159esn\u011b tam, kam je pl\xe1nek vedl, v s\xe1le dinosaur\u016f. Sv\xedt\xed tady jen jedna lampa. Uprost\u0159ed se ve tm\u011b r\xfdsuje n\u011bco obrovsk\xe9ho.")
B.aqc=s(["\u201eEmo\u2026 to obrovsk\xe9 cosi\u2026 se pr\xe1v\u011b pohnulo?\u201c"],t.s)
B.bl2=new A.a6(B.aS,B.aqc,!1)
B.axx=new A.aO("Ze tmy se ozve tich\xe9, dlouh\xe9, kostnat\xe9 zask\u0159\xedp\xe1n\xed.")
B.ae9=s(["\u201e\u0158ekn\u011bte mi, \u017ee to byly dve\u0159e.\u201c"],t.s)
B.biw=new A.a6(B.aZ,B.ae9,!1)
B.agb=s([B.axL,B.bl2,B.axx,B.biw],t.a)
B.bmY=new A.cl("story_04",B.agb)
B.aws=new A.aO("Posledn\xed kost zapadne na sv\xe9 m\xedsto. Kostra se zachv\u011bje, pomalu zvedne hlavu\u2026 a uk\xe1\u017ee \u010delist\xed k p\xedskovi\u0161ti v rohu s\xe1lu.")
B.aka=s(["\u201eEhm. D\u011bkujeme?\u201c"],t.s)
B.blQ=new A.a6(B.aM,B.aka,!1)
B.acB=s(["\u201eRozum\xedm tomu spr\xe1vn\u011b, \u017ee n\xe1m pr\xe1v\u011b poradil dinosaurus?\u201c"],t.s)
B.biS=new A.a6(B.aZ,B.acB,!1)
B.axg=new A.aO("P\xedskovi\u0161t\u011b ale vypad\xe1 \xfapln\u011b oby\u010dejn\u011b. Hromada p\xedsku a v n\xed\u2026 nic.")
B.aqr=s(["\u201e\u017d\xe1dn\xe1 cedulka. \u017d\xe1dn\xfd vzkaz. \u017d\xe1dn\xe1 \u0161ipka \u201aKl\xed\u010d je tady\u2018. To je teda pomoc.\u201c"],t.s)
B.bjr=new A.a6(B.aZ,B.aqr,!1)
B.agD=s([B.aws,B.blQ,B.biS,B.axg,B.bjr],t.a)
B.bng=new A.cl("story_05",B.agD)
B.aw5=new A.aO("P\xedskovi\u0161t\u011b se ot\u0159ese, zadun\xed a p\xedsek vyst\u0159el\xed a\u017e ke stropu. Kdy\u017e se prach usad\xed, le\u017e\xed uprost\u0159ed kr\xe1teru zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm vyryt\xe1 kost. Jon\xe1\u0161 vyt\xe1hne vzkaz.")
B.apD=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d.\u2018 Jen\u017ee tohle nen\xed cel\xfd kl\xed\u010d. Je to jen kus!\u201c"],t.s)
B.bkO=new A.a6(B.aS,B.apD,!1)
B.ah1=s(["\u201eTak\u017ee zbytek bude schovan\xfd n\u011bkde jinde v muzeu.\u201c"],t.s)
B.bin=new A.a6(B.aZ,B.ah1,!1)
B.avX=new A.aO("Lampa zablik\xe1 a zhasne. Ve tm\u011b se ozve dlouh\xe9, ospal\xe9 z\xedvnut\xed. Kdy\u017e se lampa znovu rozsv\xedt\xed, v s\xe1le nikdo nen\xed.")
B.alT=s(["\u201eKdo z v\xe1s to byl?\u201c"],t.s)
B.bii=new A.a6(B.aM,B.alT,!1)
B.aoD=s(["\u201eJ\xe1 ne!\u201c"],t.s)
B.bk_=new A.a6(B.aS,B.aoD,!1)
B.amP=s([B.aw5,B.bkO,B.bin,B.avX,B.bii,B.bk_],t.a)
B.bnb=new A.cl("story_06",B.amP)
B.ax0=new A.aO("D\u011bti doraz\xed do dal\u0161\xedho s\xe1lu. Je chladn\xfd a tajemn\u011b tich\xfd. Jde o egyptsk\xfd s\xe1l, je pln\xfd sarkof\xe1g\u016f, mumi\xed a soch d\xe1vn\xfdch boh\u016f. Mal\xfdm oknem pod stropem dopad\xe1 m\u011bs\xed\u010dn\xed sv\u011btlo.")
B.aiE=s(["\u201eTady n\u011bkde mo\u017en\xe1 bude dal\u0161\xed kus. Jen\u017ee kde?\u201c"],t.s)
B.biA=new A.a6(B.aS,B.aiE,!1)
B.axk=new A.aO("V rohu s\xe1lu le\u017e\xed v podlaze t\u011b\u017ek\xe1 kamenn\xe1 deska. Nehne se ani o milimetr. Ema se do n\xed op\u0159e celou vahou.")
B.al0=s(["\u201eJ\xe1 jsem v\u011bd\u011bla, \u017ee jsem m\u011bla r\xe1no sn\xedst ty dva rohl\xedky nav\xedc. \u201c"],t.s)
B.bjE=new A.a6(B.aM,B.al0,!1)
B.ard=s([B.ax0,B.biA,B.axk,B.bjE],t.a)
B.bmT=new A.cl("story_07",B.ard)
B.axh=new A.aO("M\u011bs\xed\u010dn\xed paprsek dopadne na vytesan\xfd symbol oka a ten se rozz\xe1\u0159\xed zlat\xfdm sv\u011btlem. K\xe1men zahu\u010d\xed, deska v rohu odjede stranou a odkryje schody. Vedou hluboko pod zem.")
B.adc=s(["\u201eSchody do nezn\xe1ma. No jasn\u011b. Schody do cukr\xe1rny to asi nebudou, co?\u201c"],t.s)
B.bkV=new A.a6(B.aZ,B.adc,!1)
B.awR=new A.aO("Jon\xe1\u0161 se zastav\xed na prvn\xedm schodu. Nohy ho necht\u011bj\xed poslechnout. Nela mu str\u010d\xed do ruky baterku.")
B.aeN=s(["\u201eSpr\xe1vn\xfd gentleman jde p\u0159ece prvn\xed, ne?\u201c"],t.s)
B.bl7=new A.a6(B.aZ,B.aeN,!1)
B.axb=new A.aO("Jon\xe1\u0161 se zhluboka nadechne.")
B.adv=s(["\u201eD-dob\u0159e. Jdu prvn\xed. Rychle, ne\u017e si to rozmysl\xedm.\u201c"],t.s)
B.bkw=new A.a6(B.aS,B.adv,!1)
B.abD=s([B.axh,B.bkV,B.awR,B.bl7,B.axb,B.bkw],t.a)
B.bmU=new A.cl("story_08",B.abD)
B.awM=new A.aO("Dole je hrobka. Je tu dusno, tma a ticho. Najednou to v\u0161ude zachrast\xed. Ze tmy vyb\u011bhnou drobn\xed brouci a rozprchnou se po cel\xe9 hrobce.")
B.amK=s(["\u201eFuj! Brouci! \u017div\xed brouci!\u201c"],t.s)
B.bkl=new A.a6(B.aS,B.amK,!1)
B.adS=s(["\u201eKlid, Jon\xe1\u0161i. Jsou to jen brouci.\u201c"],t.s)
B.blv=new A.a6(B.aM,B.adS,!1)
B.aeu=s(["\u201eTo jsou skarabeov\xe9. Posv\xe1tn\xed brouci Egyp\u0165an\u016f. Ale je mi jedno, jak moc jsou posv\xe1tn\xed. Hlavn\u011b a\u0165 mi nelezou do bot.\u201c"],t.s)
B.bkj=new A.a6(B.aS,B.aeu,!1)
B.amT=s(["\u201eJon\xe1\u0161i, te\u010f se neh\xfdbej. Jeden ti sed\xed na hlav\u011b.\u201c"],t.s)
B.blN=new A.a6(B.aZ,B.amT,!1)
B.agJ=s(["\u201eCo\u017ee?! Sundejte ho! Sundejte ho ze m\u011b!\u201c"],t.s)
B.bkM=new A.a6(B.aS,B.agJ,!1)
B.aeg=s(["\u201eD\u011bl\xe1m si legraci.\u201c"],t.s)
B.bja=new A.a6(B.aZ,B.aeg,!1)
B.aiH=s([B.awM,B.bkl,B.blv,B.bkj,B.blN,B.bkM,B.bja],t.a)
B.bmI=new A.cl("story_09",B.aiH)
B.aw1=new A.aO("V\xedr v m\xedse se zpomal\xed, zastav\xed a zmiz\xed. T\u011b\u017ek\xe9 v\xedko se se sk\u0159\xedp\u011bn\xedm odsune stranou. Pod n\xedm vedou schody je\u0161t\u011b o n\u011bco hloub\u011bji.")
B.afe=s(["\u201eMuzeum m\xe1 v\xedc pater pod zem\xed ne\u017e nad n\xed. To n\xe1m nikdo na prohl\xeddce ne\u0159ekl. Asi pod\xe1m st\xed\u017enost.\u201c"],t.s)
B.bk1=new A.a6(B.aZ,B.afe,!1)
B.axB=new A.aO("D\u011bti slezou dol\u016f a ocitnou se v mal\xe9m s\xe1le. \u017d\xe1dn\xe9 dve\u0159e. Nic. Jen k\xe1men a ticho.")
B.ahp=s(["\u201eNic tu nen\xed. Poj\u010fme rad\u0161i zp\xe1tky nahoru, dokud je\u0161t\u011b m\u016f\u017eeme.\u201c"],t.s)
B.bkq=new A.a6(B.aS,B.ahp,!1)
B.apY=s(["\u201eNikam nejdeme. Tady n\u011bco mus\xed b\xfdt.\u201c"],t.s)
B.bkx=new A.a6(B.aM,B.apY,!1)
B.aic=s(["\u201eV pohod\u011b. Jsme jen hluboko pod zem\xed, v s\xe1le bez dve\u0159\xed, uprost\u0159ed noci, v muzeu, kter\xe9 n\xe1s nechce pustit. Co by se asi tak mohlo st\xe1t?\u201c"],t.s)
B.biV=new A.a6(B.aZ,B.aic,!1)
B.ab5=s([B.aw1,B.bk1,B.axB,B.bkq,B.bkx,B.biV],t.a)
B.bn9=new A.cl("story_10",B.ab5)
B.axe=new A.aO("Pod prvn\xedm podstavcem se otev\u0159ou padac\xed dv\xed\u0159ka. Podstavec propadne do tmy a z jeho m\xedsta pomalu vystoup\xed zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm oko.")
B.aqO=s(["\u201eDal\u0161\xed kus!\u201c"],t.s)
B.bk0=new A.a6(B.aS,B.aqO,!1)
B.aeG=s(["\u201eVid\xedte? Pohoda. Tohle d\xe1me levou zadn\xed.\u201c"],t.s)
B.bj3=new A.a6(B.aM,B.aeG,!1)
B.aw2=new A.aO("D\u011bti vy\u0161plhaj\xed zp\xe1tky nahoru. Potom se odn\u011bkud z d\xe1lky ozve kovov\xe9 \u0159in\u010den\xed a slab\xfd, chraplav\xfd hlas:")
B.aC=new A.ki("clockmaker","assets/images/stories/museum/story/portrait_clockmaker.webp")
B.adj=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo? Pros\xedm v\xe1s\u2026 kolik je hodin?\u201c"],t.s)
B.blM=new A.a6(B.aC,B.adj,!0)
B.axy=new A.aO("Hlas jde z ryt\xed\u0159sk\xe9ho s\xe1lu. Vstupn\xed chodbu ale zav\xedr\xe1 t\u011b\u017ek\xe1 \u017eelezn\xe1 m\u0159\xed\u017e. Za m\u0159\xed\u017e\xed je tma a v t\xe9 tm\u011b n\u011bkdo je.")
B.alQ=s(["\u201eKone\u010dn\u011b! Lid\xe9! Ne\u0159\xedkejte mi, \u017ee se mi jenom zd\xe1te.\u201c"],t.s)
B.bll=new A.a6(B.aC,B.alQ,!0)
B.aoF=s(["\u201eKdo jste?\u201c"],t.s)
B.bl0=new A.a6(B.aM,B.aoF,!1)
B.adG=s(["\u201eTo je velmi dobr\xe1 ot\xe1zka. A\u017e na to p\u0159ijdu, \u0159eknu v\xe1m to.\u201c"],t.s)
B.blO=new A.a6(B.aC,B.adG,!0)
B.ax6=new A.aO("D\u011bti se chyt\xed m\u0159\xed\u017ee a zat\xe1hnou ze v\u0161ech sil. Tla\u010d\xed, lomcuj\xed s n\xed, ale m\u0159\xed\u017e se nehne ani o kousek.")
B.apk=s([B.axe,B.bk0,B.bj3,B.aw2,B.blM,B.axy,B.bll,B.bl0,B.blO,B.ax6],t.a)
B.bmE=new A.cl("story_11",B.apk)
B.ax4=new A.aO("M\u0159\xed\u017e s rachotem vyjede vzh\u016fru a v chodb\u011b se rozsv\xedt\xed. Na zemi tam sed\xed star\xfd mu\u017e v pracovn\xed z\xe1st\u011b\u0159e. Na nose m\xe1 br\xfdle, na \u010dele hodin\xe1\u0159skou lupu a ve vlasech pavu\u010dinu.")
B.agI=s(["\u201eD\u011bkuji. Mnohokr\xe1t d\u011bkuji. Kolik je hodin?\u201c"],t.s)
B.biP=new A.a6(B.aC,B.agI,!1)
B.awS=new A.aO("Nela se pod\xedv\xe1 na mobil.")
B.am6=s(["\u201eNev\xedm. Mobily ukazuj\xed 00:00, vypad\xe1 to, \u017ee se zasekly.\u201c"],t.s)
B.bkH=new A.a6(B.aZ,B.am6,!1)
B.aqs=s(["\u201ePo\u0159\xe1d p\u016flnoc? To je zvl\xe1\u0161tn\xed. Kdy\u017e mne sem n\u011bkdo zav\u0159el, zastavily se v\u0161echny hodiny p\u0159esn\u011b o p\u016flnoci. Bim, bam! Kukuk! Pardon. To se mi te\u010f n\u011bjak st\xe1v\xe1.\u201c"],t.s)
B.bl6=new A.a6(B.aC,B.aqs,!1)
B.awL=new A.aO("Jon\xe1\u0161 uk\xe1\u017ee na z\xe1st\u011bru.")
B.aj2=s(["\u201eTady m\xe1te jmenovku. \u201aMistr Vav\u0159inec Tikal, hodin\xe1\u0159 muzea.\u2018\u201c"],t.s)
B.bjh=new A.a6(B.aS,B.aj2,!1)
B.amx=s(["\u201eVav\u0159inec Tikal! No jist\u011b, to jsem j\xe1! J\xe1 tu\u0161il, \u017ee m\xe1m n\u011bco spole\u010dn\xe9ho s hodinami.\u201c"],t.s)
B.biy=new A.a6(B.aC,B.amx,!1)
B.amm=s([B.ax4,B.biP,B.awS,B.bkH,B.bl6,B.awL,B.bjh,B.biy],t.a)
B.bn7=new A.cl("story_12",B.amm)
B.aqI=s(["\u201eV. T.! To vy jste napsal ten vzkaz!\u201c"],t.s)
B.biZ=new A.a6(B.aM,B.aqI,!1)
B.awo=new A.aO("Jon\xe1\u0161 mu uk\xe1\u017ee vzkaz ze \u0161atny. Hodin\xe1\u0159 zbledne.")
B.apT=s(["\u201eTo je opravdu moje p\xedsmo. Krasopis! Jedni\u010dka s hv\u011bzdi\u010dkou! Ale kdy bych to psal? A pro\u010d?\u201c"],t.s)
B.bkG=new A.a6(B.aC,B.apT,!1)
B.adJ=s(["\u201eA kdo v\xe1s zav\u0159el?\u201c"],t.s)
B.bkU=new A.a6(B.aM,B.adJ,!1)
B.aoY=s(["\u201eJedna pan\xed. Byla kr\xe1sn\xe1, ale hrozn\u011b unaven\xe1. Nab\xeddla mi \u0161\xe1lek \u010daje a pak\u2026 u\u017e si nepamatuju nic, jen to, jak se usm\xedvala.\u201c"],t.s)
B.bj5=new A.a6(B.aC,B.aoY,!1)
B.awa=new A.aO("V\u0161ichni se na sebe pod\xedvaj\xed. Nikdo nic ne\u0159ekne. Ale ka\u017ed\xfd mysl\xed na tot\xe9\u017e. Hodin\xe1\u0159 se zvedne, opr\xe1\u0161\xed si z\xe1st\u011bru a zam\xed\u0159\xed s nimi k hlavn\xedmu s\xe1lu. P\u0159ed n\xedm v\u0161ak jsou ryt\xed\u0159i v pln\xe9 zbroji. Stoj\xed bok po boku a nikoho nepust\xed d\xe1l.")
B.ahX=s(["\u201eAch, p\xe1nov\xe9 ryt\xed\u0159i. Velmi d\u016fstojn\xed. A velmi tvrdohlav\xed.\u201c"],t.s)
B.blk=new A.a6(B.aC,B.ahX,!1)
B.awH=new A.aO("Nela zaklepe na brn\u011bn\xed.")
B.ae1=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo?\u201c"],t.s)
B.biO=new A.a6(B.aZ,B.ae1,!1)
B.awd=new A.aO("Brn\u011bn\xed dut\u011b zadun\xed. Ale \u017e\xe1dn\xfd z nich se ani nehne.")
B.ajC=s([B.biZ,B.awo,B.bkG,B.bkU,B.bj5,B.awa,B.blk,B.awH,B.biO,B.awd],t.a)
B.bmN=new A.cl("story_13",B.ajC)
B.awY=new A.aO("Ryt\xed\u0159i jeden po druh\xe9m zasalutuj\xed a ustoup\xed stranou.")
B.aiS=s(["\u201eOni n\xe1m zasalutovali! Vid\u011bli jste to? Zasalutovali!\u201c"],t.s)
B.bjt=new A.a6(B.aM,B.aiS,!1)
B.ar_=s(["\u201eRyt\xed\u0159sk\xe1 \u010dest. Pozor! Pohov! R\xe1z, dva, r\xe1z, dva! J\xe1 bych byl dobr\xfd ryt\xed\u0159. Jen by m\u011b ta zbroj tla\u010dila.\u201c"],t.s)
B.biM=new A.a6(B.aC,B.ar_,!1)
B.aec=s(["\u201eJe v po\u0159\xe1dku?\u201c"],t.s)
B.blS=new A.a6(B.aZ,B.aec,!1)
B.ar8=s(["\u201eTen \u010daj byl asi hodn\u011b siln\xfd.\u201c"],t.s)
B.bkf=new A.a6(B.aS,B.ar8,!1)
B.avZ=new A.aO("V\u0161ichni pokra\u010duj\xed d\xe1l do obrovsk\xe9ho s\xe1lu. Je v n\u011bm \u0161ero a podlaha pod nohama zlov\u011bstn\u011b vr\u017ee.")
B.aih=s(["\u201eTuhle podlahu jsem\u2026 opravoval. Nebo jsem ji\u2026 hmm. Tady bych na va\u0161em m\xedst\u011b \u0161el opatrn\u011b. Nev\xedm pro\u010d. Ale \u0161el bych.\u201c"],t.s)
B.bkt=new A.a6(B.aC,B.aih,!1)
B.af1=s(["\u201eTo je stra\u0161n\u011b uklid\u0148uj\xedc\xed.\u201c"],t.s)
B.bis=new A.a6(B.aZ,B.af1,!1)
B.age=s([B.awY,B.bjt,B.biM,B.blS,B.bkf,B.avZ,B.bkt,B.bis],t.a)
B.bn0=new A.cl("story_14",B.age)
B.awl=new A.aO("Deska se ot\u0159ese a pole se jedno po druh\xe9m propadaj\xed do tmy. K\u016f\u0148 stihne na posledn\xed chv\xedli odsko\u010dit do bezpe\u010d\xed. Z temn\xe9 j\xe1my vylet\xed zlat\xfd \xfalomek kl\xed\u010de se \u0161t\xedtem.")
B.ahd=s(["\u201eBum! To byla ale kr\xe1sa!\u201c"],t.s)
B.blV=new A.a6(B.aC,B.ahd,!1)
B.axr=new A.aO("V\u0161ichni se na n\u011bj pod\xedvaj\xed.")
B.acU=s(["\u201e\u2026Ehm. Pardon. Chci \u0159\xedct: to bylo velmi nebezpe\u010dn\xe9.\u201c"],t.s)
B.bjm=new A.a6(B.aC,B.acU,!1)
B.aoM=s(["\u201eA dal\u0161\xed kus.\u201c"],t.s)
B.bjn=new A.a6(B.aS,B.aoM,!1)
B.apA=s(["\u201eA kolik jich jako je\u0161t\u011b m\xe1 b\xfdt?\u201c"],t.s)
B.biQ=new A.a6(B.aZ,B.apA,!1)
B.axm=new A.aO("Hodin\xe1\u0159 prom\u011b\u0159uje \xfalomek lupou.")
B.aiw=s(["\u201eKl\xed\u010d\u2026 To je moje pr\xe1ce. Tenhle kl\xed\u010d jsem kdysi vyrobil. Pro\u010d je ulomen\xfd? Kdo by\u2026 Ach ne.\u201c"],t.s)
B.bl8=new A.a6(B.aC,B.aiw,!1)
B.aaO=s([B.awl,B.blV,B.axr,B.bjm,B.bjn,B.biQ,B.axm,B.bl8],t.a)
B.bmM=new A.cl("story_15",B.aaO)
B.axJ=new A.aO("Cesta k dal\u0161\xedmu s\xe1lu vede p\u0159es vstupn\xed halu. Kolem obrazu baronky proch\xe1zej\xed po \u0161pi\u010dk\xe1ch. Jon\xe1\u0161 se nechce d\xedvat, ale nakonec se stejn\u011b pod\xedv\xe1. Obraz je pr\xe1zdn\xfd. Z\u016fstalo jen osam\u011bl\xe9 k\u0159eslo.")
B.ap6=s(["\u201eKde je?\u201c"],t.s)
B.blG=new A.a6(B.aS,B.ap6,!1)
B.axp=new A.aO("Jon\xe1\u0161 mrkne. A baronka je zase zp\u011bt v obraze. Sp\xed a usm\xedv\xe1 se\u2026")
B.ajB=s(["\u201eTo je ona. Pan\xed baronka.\u201c"],t.s)
B.bk5=new A.a6(B.aC,B.ajB,!1)
B.aoL=s(["\u201eTo ona je ta pan\xed s \u010dajem? Ona v\xe1s zav\u0159ela?\u201c"],t.s)
B.bjk=new A.a6(B.aM,B.aoL,!1)
B.afi=s(["\u201eMo\u017en\xe1\u2026 Nev\xedm. Moje hlava je sam\xe1 d\xedra\u2026 jako ement\xe1l.\u201c"],t.s)
B.blF=new A.a6(B.aC,B.afi,!1)
B.afa=s(["\u201eAle vy jste p\u0159ece ten kl\xed\u010d vyrobil. Kdy\u017e si vzpomenete, zjist\xedme, kde je zbytek!\u201c"],t.s)
B.biR=new A.a6(B.aM,B.afa,!1)
B.aol=s(["\u201eAlchymista m\u011bl naho\u0159e ve v\u011b\u017ei svou laborato\u0159. On m\u011bl v\u017edycky l\xe9k na v\u0161echno.\u201c"],t.s)
B.bjj=new A.a6(B.aC,B.aol,!1)
B.ajj=s(["\u201eDob\u0159e, jdeme tam.\u201c"],t.s)
B.bjX=new A.a6(B.aM,B.ajj,!1)
B.awZ=new A.aO("Hodin\xe1\u0159 vede d\u011bti po to\u010dit\xfdch schodech nahoru do v\u011b\u017ee, do laborato\u0159e star\xe9ho alchymisty. V laborato\u0159i je ticho a v\u0161ude le\u017e\xed prach.")
B.acg=s(["\u201eTak, pane alchymisto. Kde m\xe1te ten l\xe9k na v\u0161echno?\u201c"],t.s)
B.bjo=new A.a6(B.aM,B.acg,!1)
B.adE=s([B.axJ,B.blG,B.axp,B.bk5,B.bjk,B.blF,B.biR,B.bjj,B.bjX,B.awZ,B.bjo],t.a)
B.bnc=new A.cl("story_16",B.adE)
B.awC=new A.aO("V knize jsou t\u0159i recepty. Tenebrikus je lektvar no\u010dn\xedho vid\u011bn\xed. Ardeon je lektvar odvahy. A Siderion je elix\xedr hv\u011bzdn\xe9ho sv\u011btla. Pod n\xe1zvem je drobn\xe9 p\xedsmo.")
B.ahA=s(["\u201e\u201aRozjasn\xed mysl a vr\xe1t\xed ztracen\xe9 vzpom\xednky. Spr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch. Polovina d\xe1vky rozjasn\xed mysl. Cel\xe1 d\xe1vka usp\xed na sto let.\u2018\u201c"],t.s)
B.bl9=new A.a6(B.aS,B.ahA,!1)
B.aw8=new A.aO("Kdy\u017e se obr\xe1t\xed posledn\xed list, le\u017e\xed na n\u011bm zlat\xfd \xfalomek kl\xed\u010de s hv\u011bzdou.")
B.aqk=s(["\u201eDal\u0161\xed kus kl\xed\u010de! A k tomu recept na pam\u011b\u0165. Dneska m\xe1me \u0161\u0165astn\xfd den.\u201c"],t.s)
B.bk4=new A.a6(B.aM,B.aqk,!1)
B.aoc=s(["\u201eEmo, jsme zav\u0159en\xed v muzeu.\u201c"],t.s)
B.bjs=new A.a6(B.aZ,B.aoc,!1)
B.ahg=s(["\u201e\u0160\u0165astn\xfd den v r\xe1mci mo\u017enost\xed.\u201c"],t.s)
B.blz=new A.a6(B.aM,B.ahg,!1)
B.and=s(["\u201e\u201aSpr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch.\u2018 Hv\u011bzdy ale odsud v\u016fbec nejsou vid\u011bt.\u201c"],t.s)
B.blb=new A.a6(B.aS,B.and,!1)
B.awz=new A.aO("Nela uk\xe1\u017ee na \xfazk\xe9 sch\u016fdky v rohu.")
B.akn=s(["\u201eCo zkusit schody?\u201c"],t.s)
B.bki=new A.a6(B.aZ,B.akn,!1)
B.aw7=new A.aO("Sch\u016fdky vedou a\u017e na sam\xfd vrchol v\u011b\u017ee, do mal\xe9 hv\u011bzd\xe1rny. Za velk\xfdm oknem z\xe1\u0159\xed tis\xedce hv\u011bzd.")
B.ad4=s(["\u201eV\u017edy\u0165 je tu milion hv\u011bzd. Co s t\xedm m\xe1me d\u011blat?\u201c"],t.s)
B.bjc=new A.a6(B.aS,B.ad4,!1)
B.ani=s([B.awC,B.bl9,B.aw8,B.bk4,B.bjs,B.blz,B.blb,B.awz,B.bki,B.aw7,B.bjc],t.a)
B.bn1=new A.cl("story_17",B.ani)
B.axw=new A.aO("Souhv\u011bzd\xed na obloze se rozz\xe1\u0159\xed a do v\u011b\u017ee padne st\u0159\xedbrn\xe9 hv\u011bzdn\xe9 sv\u011btlo. Pomalu sklouzne po schodech dol\u016f, a\u017e do alchymistovy laborato\u0159e.")
B.abp=s(["\u201eTak\u017ee te\u010f asi ty hv\u011bzdy sv\xedt\xed spr\xe1vn\u011b. Kdo by \u0159ekl, \u017ee jdou hv\u011bzdy zapnout.\u201c"],t.s)
B.blh=new A.a6(B.aZ,B.abp,!1)
B.awb=new A.aO("D\u011bti jdou za sv\u011btlem do laborato\u0159e.")
B.aj1=s(["\u201eMn\u011b se to tu nel\xedb\xed. N\u011bkdo n\xe1s tu nechce, c\xedt\xedm to.\u201c"],t.s)
B.bka=new A.a6(B.aS,B.aj1,!1)
B.aeV=s(["\u201eAlchymista m\xedval v\u0161echno p\u0159ipraven\xe9 dop\u0159edu. Jestli ten l\xe9k n\u011bkde bude, tak ur\u010dit\u011b tady.\u201c"],t.s)
B.bkb=new A.a6(B.aC,B.aeV,!1)
B.am9=s([B.axw,B.blh,B.awb,B.bka,B.bkb],t.a)
B.bnf=new A.cl("story_18",B.am9)
B.awK=new A.aO("Hodin\xe1\u0159 vypije odm\u011b\u0159enou polovinu elix\xedru. \u0160kytne a v o\u010d\xedch mu zajisk\u0159\xed drobn\xe9 hv\u011bzdi\u010dky.")
B.amf=s(["\u201eLevandule! Ten \u010daj byl levandulov\xfd. A ona \u0159\xedkala: \u201aBu\u010fte tak laskav, mist\u0159e Tikale. Jenom zastavte hodiny. Jenom na chvilku.\u2018 Potom za\u0161eptala: \u201aJenom nav\u017edy.\u2018 Myslel jsem, \u017ee jsem \u0161patn\u011b rozum\u011bl. A pak\u2026 u\u017e si nic nepamatuju.\u201c"],t.s)
B.bkg=new A.a6(B.aC,B.amf,!1)
B.aju=s(["\u201eJak\xe9 hodiny?\u201c"],t.s)
B.bk3=new A.a6(B.aS,B.aju,!1)
B.agg=s(["\u201eTo je\u0161t\u011b nev\xedm. Ale v\xedm, kde to zjist\xedme.\u201c"],t.s)
B.biJ=new A.a6(B.aC,B.agg,!1)
B.axC=new A.aO("Druhou polovinu elix\xedru hodin\xe1\u0159 pe\u010dliv\u011b zaz\xe1tkuje a schov\xe1 do kapsy z\xe1st\u011bry.")
B.ail=s(["\u201eNa hor\u0161\xed \u010dasy.\u201c"],t.s)
B.biD=new A.a6(B.aC,B.ail,!1)
B.axD=new A.aO("V tu chv\xedli se ze schodi\u0161t\u011b pod nimi oz\xfdv\xe1 tich\xe9 \u0161ust\u011bn\xed. Pomal\xfdmi kroky jde n\u011bkdo nahoru. V d\xe1lce se oz\xfdv\xe1 ospal\xfd hlas:")
B.amF=s(["\u201eWas ist das\u2026? Kdo m\u011b to zase ru\u0161\xed\u2026? Ruhe\u2026 Ruhe\u2026\u201c"],t.s)
B.bkQ=new A.a6(B.xd,B.amF,!0)
B.aeF=s([B.awK,B.bkg,B.bk3,B.biJ,B.axC,B.biD,B.axD,B.bkQ],t.a)
B.bn5=new A.cl("story_19",B.aeF)
B.axz=new A.aO("Kroky se zastav\xed za dve\u0159mi a v\u0161ichni ztuhnou. Ozve se jen dlouh\xe9, ospal\xe9 z\xedvnut\xed. Pak \u0161ust\u011bn\xed sukn\xed pomalu sl\xe1bne, a\u017e utichne \xfapln\u011b.")
B.aml=s(["\u201eJe pry\u010d. Vr\xe1tila se do obrazu. O\u010dividn\u011b moc dlouho venku nevydr\u017e\xed.\u201c"],t.s)
B.biL=new A.a6(B.aS,B.aml,!1)
B.ahE=s(["\u201eTak toho vyu\u017eijeme. Rychle dol\u016f!\u201c"],t.s)
B.bkL=new A.a6(B.aM,B.ahE,!1)
B.awT=new A.aO("D\u011bti jdou tmou za hodin\xe1\u0159em. Vede je dlouhou chodbou a\u017e k n\xedzk\xfdm dve\u0159\xedm.")
B.afo=s(["\u201eMoje d\xedlna! Kdo mi tady ud\u011blal takov\xfd nepo\u0159\xe1dek? Aha. J\xe1. Tady b\xfdval v\u017edycky po\u0159\xe1dek. Ka\u017ed\xe9 hodiny v\u011bd\u011bly, kolik je hodin. Te\u010f nev\u011bd\xed nic. Ani jedny. Jako j\xe1.\u201c"],t.s)
B.biU=new A.a6(B.aC,B.afo,!1)
B.ao7=s([B.axz,B.biL,B.bkL,B.awT,B.biU],t.a)
B.bmW=new A.cl("story_20",B.ao7)
B.aw_=new A.aO("N\xe1st\u011bnn\xe9 hodiny odbij\xed p\u016flnoc a v\u0161echny bud\xedky se ozvou s nimi. Zvon\xed, cinkaj\xed a rachot\xed. Pak v\u0161echny zase ztichnou a ru\u010di\u010dky se znovu zastav\xed. A na podlaze pod pracovn\xedm stolem n\u011bco le\u017e\xed.")
B.aqN=s(["\u201eMoje bed\xfdnka! Moje sou\u010d\xe1stky! Pades\xe1t let jsem je t\u0159\xeddil!\u201c"],t.s)
B.bj9=new A.a6(B.aC,B.aqN,!1)
B.ax_=new A.aO("Hodin\xe1\u0159 si k bed\xfdnce klekne a n\u011b\u017en\u011b ji hlad\xed.")
B.afZ=s(["\u201eTahle bed\xfdnka byla v\u017edycky na sv\xe9m m\xedst\u011b. A v\u0161echno v n\xed taky.\u201c"],t.s)
B.bjq=new A.a6(B.aC,B.afZ,!1)
B.ako=s([B.aw_,B.bj9,B.ax_,B.bjq],t.a)
B.bnh=new A.cl("story_21",B.ako)
B.awO=new A.aO("Posledn\xed sou\u010d\xe1stka zapadne na sv\xe9 m\xedsto a pod bed\xfdnkou se zaleskne zlat\xfd \xfalomek kl\xed\u010de s kole\u010dkem. Hodin\xe1\u0159 vezme bed\xfdnku do rukou. Chv\xedli se na ni d\xedv\xe1. A pak se mu v o\u010d\xedch rozsv\xedt\xed. Tentokr\xe1t doopravdy.")
B.aex=s(["\u201eU\u017e si vzpom\xedn\xe1m. Na v\u0161echno. Za orlojem je tajn\xe1 chodba, kter\xe1 vede k srdci muzea.\u201c"],t.s)
B.bld=new A.a6(B.aC,B.aex,!1)
B.are=s(["\u201eBaronka m\u011b p\u0159inutila ho zastavit a zape\u010detit. Od t\xe9 chv\xedle je tu po\u0159\xe1d p\u016flnoc. R\xe1no nikdy nep\u0159ijde a dve\u0159e se nikdy neotev\u0159ou.\u201c"],t.s)
B.bij=new A.a6(B.aC,B.are,!1)
B.aoG=s(["\u201eA kl\xed\u010d?\u201c"],t.s)
B.biC=new A.a6(B.aS,B.aoG,!1)
B.ah5=s(["\u201eTen rozlomila ona. Kousek po kousku roznesla \xfalomky po muzeu a u ka\u017ed\xe9ho nastra\u017eila past, aby u\u017e nikdo nemohl srdce muzea znovu probudit. A j\xe1 hlup\xe1k j\xed je\u0161t\u011b sv\xedtil na cestu.\u201c"],t.s)
B.bjK=new A.a6(B.aC,B.ah5,!1)
B.aaR=s(["\u201eJen jednou se mi na chv\xedli rozjasnilo v hlav\u011b. Rychle jsem napsal vzkaz a schoval ho do sk\u0159\xed\u0148ky v \u0161atn\u011b, kde by ho baronka nikdy nehledala. Stihl jsem to t\u011bsn\u011b p\u0159edt\xedm, ne\u017e mi poru\u010dila, a\u0165 se zav\u0159u za m\u0159\xed\u017e. A pak u\u017e jsem si nepamatoval nic.\u201c"],t.s)
B.bjz=new A.a6(B.aC,B.aaR,!1)
B.aqT=s(["\u201eAle pro\u010d to ud\u011blala?\u201c"],t.s)
B.bjZ=new A.a6(B.aM,B.aqT,!1)
B.agf=s([B.awO,B.bld,B.bij,B.biC,B.bjK,B.bjz,B.bjZ],t.a)
B.bne=new A.cl("story_22",B.agf)
B.aoN=s(["\u201eZ\xedtra r\xe1no ji maj\xed odv\xe9zt do nov\xe9 galerie na n\xe1dra\u017e\xed. Mezi vlaky, hl\xe1\u0161en\xed a tis\xedce lid\xed. L\xe9ta tady nem\u016f\u017ee usnout kv\u016fli n\xe1v\u0161t\u011bvn\xedk\u016fm. A tam by neusnula u\u017e nikdy.\u201c"],t.s)
B.bjN=new A.a6(B.aC,B.aoN,!1)
B.aig=s(["\u201eTo je vlastn\u011b\u2026 trochu smutn\xe9.\u201c"],t.s)
B.biI=new A.a6(B.aM,B.aig,!1)
B.aox=s(["\u201eJen\u017ee j\xed je \xfapln\u011b jedno, \u017ee tu n\u011bkoho zamkne. A \u017ee se muzeum u\u017e nikdy neotev\u0159e. To je teda p\u011bkn\u011b sobeck\xe9.\u201c"],t.s)
B.bkW=new A.a6(B.aZ,B.aox,!1)
B.awE=new A.aO("Hodin\xe1\u0159 je zavede do rohu d\xedlny. Stoj\xed tam orloj, na kter\xe9m hodin\xe1\u0159 pracoval cel\xfd \u017eivot. Te\u010f ml\u010d\xed.")
B.ahP=s(["\u201eMoje nejkr\xe1sn\u011bj\u0161\xed pr\xe1ce. A cesta k srdci muzea. Jen\u017ee jsem ho musel rozebrat.\u201c"],t.s)
B.biF=new A.a6(B.aC,B.ahP,!1)
B.alV=s(["\u201eTak to oprav\xedme. Ur\u010dit\u011b to nebude t\u011b\u017ek\xe9.\u201c"],t.s)
B.bkS=new A.a6(B.aM,B.alV,!1)
B.afg=s(["\u201eTo sam\xe9 jsi \u0159\xedkala o tom pl\xe1nu se \u0161atnou. A pod\xedvej, kde jsme.\u201c"],t.s)
B.blH=new A.a6(B.aZ,B.afg,!1)
B.ajw=s([B.bjN,B.biI,B.bkW,B.awE,B.biF,B.bkS,B.blH],t.a)
B.bn_=new A.cl("story_23",B.ajw)
B.awB=new A.aO("Orloj se nadechne. Ru\u010di\u010dky se rozeb\u011bhnou a dv\xed\u0159ka dole se pomalu otev\u0159ou. Za nimi je \xfazk\xe1 chodba a na jej\xedm konci podivn\xe9 sv\u011btlo.")
B.apV=s(["\u201eTajn\xe1 chodba! Poj\u010fte!\u201c"],t.s)
B.bkn=new A.a6(B.aM,B.apV,!1)
B.axq=new A.aO("Chodba za orlojem kon\u010d\xed ve skryt\xe9 hale s vysok\xfdm stropem. Uprost\u0159ed zdi vis\xed obrovsk\xe9 hodiny, p\u0159es cifern\xedk maj\xed rudou pe\u010de\u0165.")
B.anX=s(["\u201eSrdce muzea.\u201c"],t.s)
B.bkP=new A.a6(B.aC,B.anX,!1)
B.awG=new A.aO("Za jejich z\xe1dy za\u0161ust\xed \u0161aty.")
B.axF=new A.aO("Ve dve\u0159\xedch haly stoj\xed baronka Frida von Schlafenberg. Skute\u010dn\xe1 a \u017eiv\xe1, vystoupila z obrazu. Je mnohem vy\u0161\u0161\xed, ne\u017e si mysleli. A hrozn\u011b, hrozn\u011b ospal\xe1.")
B.amg=s(["\u201eKinder\u2026 D\u011bti. Pro\u010d jste tak hlu\u010dn\xe9? Sto let. Sto let jsem neusnula. Nechte ty hodiny sp\xe1t. Bitte\u2026\u201c"],t.s)
B.bjw=new A.a6(B.xd,B.amg,!1)
B.axu=new A.aO("Ema ud\u011bl\xe1 krok dop\u0159edu a postav\xed se p\u0159ed ostatn\xed. Baronka k n\xed nat\xe1hne ruku. Ale v p\u016fli pohybu se j\xed zav\u0159ou o\u010di. Pomalu se sesune na schod, polo\u017e\xed hlavu na ruku\u2026 a usne. Jej\xed postava zbledne, zpr\u016fhledn\xed a rozplyne se.")
B.aib=s(["\u201eVr\xe1tila se do obrazu?\u201c"],t.s)
B.bk8=new A.a6(B.aZ,B.aib,!1)
B.af6=s(["\u201eVypad\xe1 to tak. Ale nev\xedme, na jak dlouho.\u201c"],t.s)
B.bjy=new A.a6(B.aS,B.af6,!1)
B.ag3=s(["\u201eTak si mus\xedme posp\xed\u0161it. Pom\u016f\u017eete star\xe9mu hodin\xe1\u0159i? Je\u0161t\u011b naposledy?\u201c"],t.s)
B.bjQ=new A.a6(B.aC,B.ag3,!1)
B.ar9=s([B.awB,B.bkn,B.axq,B.bkP,B.awG,B.axF,B.bjw,B.axu,B.bk8,B.bjy,B.bjQ],t.a)
B.bmF=new A.cl("story_24",B.ar9)
B.awD=new A.aO("\xdalomky se zatav\xed do vosku a pe\u010de\u0165 se rozz\xe1\u0159\xed. Pak praskne a rozlet\xed se na kusy. Pod n\xed se objev\xed cifern\xedk. Ru\u010di\u010dky ukazuj\xed p\u016flnoc. Hodiny se zhluboka nadechnou\u2026 a rozb\u011bhnou se. Po cel\xe9m muzeu se rozezn\xed tik\xe1n\xed v\u0161ech hodin najednou. Ru\u010di\u010dky ute\u010dou od p\u016flnoci, v okn\u011b chodby je vid\u011bt \xfasvit a z\xe1mky v\u0161ech dve\u0159\xed v muzeu cvaknou.")
B.ao9=s(["\u201eSly\u0161\xedte to? Muzeum zase d\xfdch\xe1. Srdce muzea je tajemstv\xed, nikdo ho tu nesm\xed naj\xedt a v\xe1s tak\xe9 ne. Tuhle chodbu zase schov\xe1m. Z\u016fstanu tady a d\xe1m do po\u0159\xe1dku v\u0161echno, co tu baronka provedla. Hodiny u\u017e nikomu nedovol\xedm zastavit. Ani za \u0161\xe1lek levandulov\xe9ho \u010daje.\u201c"],t.s)
B.bkp=new A.a6(B.aC,B.ao9,!1)
B.amR=s(["\u201eA posp\u011b\u0161te si. Baronka te\u010f tvrd\u011b sp\xed. Ale dokud je muzeum zav\u0159en\xe9, m\u016f\u017ee kdykoli vystoupit z obrazu. Otev\u0159ete hlavn\xed dve\u0159e, ne\u017e se vzbud\xed.\u201c"],t.s)
B.bjP=new A.a6(B.aC,B.amR,!1)
B.aiz=s([B.awD,B.bkp,B.bjP],t.a)
B.bmy=new A.cl("story_25",B.aiz)
B.axf=new A.aO("Ema ho obejme. Jon\xe1\u0161 mu pod\xe1 ruku. Nela mu vyt\xe1hne pavu\u010dinu z vlas\u016f. Zvenku se ozve motor n\xe1kladn\xedho auta, st\u011bhov\xe1ci p\u0159ijeli pro obraz baronky. D\u011bti b\u011b\u017e\xed zp\xe1tky do vstupn\xed haly. Baronka v obraze sp\xed a usm\xedv\xe1 se. Jen\u017ee hlavn\xed dve\u0159e se po\u0159\xe1d nehnou.")
B.ag7=s(["\u201eZ\xe1mky p\u0159ece cvakly. Tak pro\u010d se ty dve\u0159e neotev\u0159ou?\u201c"],t.s)
B.blg=new A.a6(B.aZ,B.ag7,!1)
B.aoT=s(["\u201eH\xe1d\xe1m, \u017ee tohle je posledn\xed past pan\xed baronky.\u201c"],t.s)
B.bjO=new A.a6(B.aM,B.aoT,!1)
B.awP=new A.aO("Baronka v obraze se zavrt\xed a ze span\xed vzdychne. D\u011bti ztuhnou.")
B.afK=s(["\u201eRychle. A potichu.\u201c"],t.s)
B.blB=new A.a6(B.aM,B.afK,!1)
B.aip=s([B.axf,B.blg,B.bjO,B.awP,B.blB],t.a)
B.bnd=new A.cl("story_26",B.aip)
B.axH=new A.aO("Posledn\xed z\xe1str\u010dka cvakne. T\u011b\u017ek\xe1 k\u0159\xeddla dve\u0159\xed se pomalu otev\u0159ou a do haly vtrhne rann\xed sv\u011btlo. Rozlije se po podlaze, po zdech a nakonec dopadne i na obraz.")
B.ajQ=s(["\u201eJe otev\u0159eno! Muzeum je otev\u0159en\xe9!\u201c"],t.s)
B.blo=new A.a6(B.aM,B.ajQ,!1)
B.aiq=s(["\u201ePod\xedvejte na obraz. Pan\xed baronce n\u011bjak ztuhl \xfasm\u011bv.\u201c"],t.s)
B.bkC=new A.a6(B.aZ,B.aiq,!1)
B.aw9=new A.aO("Tv\xe1\u0159 baronky se pomalu zamra\u010d\xed. U\u017e se nepohne.")
B.ahc=s(["\u201eTak to bychom m\u011bli. A te\u010f honem pry\u010d, ne\u017e n\xe1s tu n\u011bkdo najde.\u201c"],t.s)
B.bjd=new A.a6(B.aS,B.ahc,!1)
B.awQ=new A.aO("D\u011bti vyklouznou z muzea ve chv\xedli, kdy st\u011bhov\xe1ci vystupuj\xed z auta.")
B.apE=s(["\u201eZvl\xe1dli jsme to!\u201c"],t.s)
B.bk7=new A.a6(B.aM,B.apE,!1)
B.awA=new A.aO("St\u011bhov\xe1ci vejdou do muzea, po chv\xedli vyn\xe1\u0161\xed velk\xfd obraz zabalen\xfd do deky. Jeden roh deky sklouzne.")
B.aww=new A.aO("Baronka Frida von Schlafenberg sice sp\xed, ale tv\xe1\u0159\xed se tak na\u0161tvan\u011b jako je\u0161t\u011b nikdy. V\u0161imnou si toho i st\u011bhov\xe1ci. \u201eNa n\xe1dra\u017e\xed si zvykne,\u201c prohod\xed jeden ze st\u011bhov\xe1k\u016f. Potom, co auto odjede, se v okn\u011b muzea na okam\u017eik objev\xed star\xfd hodin\xe1\u0159 s lampou. K\xfdvne na n\u011b, zamrk\xe1 a zmiz\xed. Z muzea je sly\u0161et tich\xe9, spokojen\xe9 tik\xe1n\xed.")
B.apN=s(["\u201eTohle n\xe1m nikdo neuv\u011b\u0159\xed.\u201c"],t.s)
B.bln=new A.a6(B.aZ,B.apN,!1)
B.akf=s([B.axH,B.blo,B.bkC,B.aw9,B.bjd,B.awQ,B.bk7,B.awA,B.aww,B.bln],t.a)
