B.byH=new A.bq(9,"tik\xe1n\xed","sfx_story_soft_ticking",null,1)
B.akt=s([B.byD,B.bym,B.byf,B.byH],t.c)
B.b3G=new A.e(0,0,170.20355132091814,311.82330012992634)
B.b4q=new A.e(120,0,311.85794716327416,170.20355132091814)
B.b1b=new A.e(129.9,129.9,311.79692507579034,311.79692507579034)
B.kQ=s([B.b3G,B.b4q,B.b1b],t.u)
B.awW=new A.aO("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.cC=new A.ki("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.ady=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.biX=new A.a6(B.cC,B.ady,!1)
B.bN=new A.ki("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.ai4=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.bly=new A.a6(B.bN,B.ai4,!1)
B.anH=s([B.awW,B.biX,B.bly],t.a)
B.bn6=new A.cl("story_00_intro",B.anH)
B.awe=new A.aO("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.ael=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.bj6=new A.a6(B.cC,B.ael,!1)
B.ax2=new A.aO("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.aev=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.bj2=new A.a6(B.bN,B.aev,!1)
B.cK=new A.ki("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.aoZ=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.blj=new A.a6(B.cK,B.aoZ,!1)
B.aeR=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.bkB=new A.a6(B.cC,B.aeR,!1)
B.anU=s([B.awe,B.bj6,B.ax2,B.bj2,B.blj,B.bkB],t.a)
B.bmH=new A.cl("story_01a_clubhouse_arrival",B.anU)
B.agm=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.bjL=new A.a6(B.cC,B.agm,!1)
B.ais=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.bkI=new A.a6(B.cK,B.ais,!1)
B.acd=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.bl3=new A.a6(B.bN,B.acd,!1)
B.aeq=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.bl_=new A.a6(B.cK,B.aeq,!1)
B.adB=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.bk2=new A.a6(B.bN,B.adB,!1)
B.aaX=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.biH=new A.a6(B.cC,B.aaX,!1)
B.ali=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.blE=new A.a6(B.bN,B.ali,!1)
B.aqM=s([B.bjL,B.bkI,B.bl3,B.bl_,B.bk2,B.biH,B.blE],t.a)
B.bmA=new A.cl("story_01b_legend_and_time",B.aqM)
B.axG=new A.aO("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.agu=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.bjS=new A.a6(B.bN,B.agu,!1)
B.afz=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.blP=new A.a6(B.cK,B.afz,!1)
B.aq_=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.bkZ=new A.a6(B.bN,B.aq_,!1)
B.akI=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.biB=new A.a6(B.cK,B.akI,!1)
B.adg=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.biE=new A.a6(B.cC,B.adg,!1)
B.aj3=s([B.axG,B.bjS,B.blP,B.bkZ,B.biB,B.biE],t.a)
B.bmz=new A.cl("story_02_torn_map",B.aj3)
B.ace=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.bjR=new A.a6(B.cC,B.ace,!1)
B.alP=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.blp=new A.a6(B.bN,B.alP,!1)
B.awI=new A.aO("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.ap3=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.blr=new A.a6(B.cK,B.ap3,!1)
B.app=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.blw=new A.a6(B.bN,B.app,!1)
B.ak1=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.bj4=new A.a6(B.cC,B.ak1,!1)
B.acF=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.bjI=new A.a6(B.bN,B.acF,!1)
B.acN=s([B.bjR,B.blp,B.awI,B.blr,B.blw,B.bj4,B.bjI],t.a)
B.bmC=new A.cl("story_03_founders_trail",B.acN)
B.awi=new A.aO("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.af8=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.blJ=new A.a6(B.bN,B.af8,!1)
B.ala=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.bkT=new A.a6(B.cK,B.ala,!1)
B.aoI=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.bl4=new A.a6(B.bN,B.aoI,!1)
B.agP=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.bkK=new A.a6(B.cC,B.agP,!1)
B.abI=s([B.awi,B.blJ,B.bkT,B.bl4,B.bkK],t.a)
B.bmw=new A.cl("story_04_flowers_in_mud",B.abI)
B.awN=new A.aO("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.ae2=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.bjf=new A.a6(B.bN,B.ae2,!1)
B.ab2=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.bkA=new A.a6(B.cK,B.ab2,!1)
B.ahr=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.blU=new A.a6(B.bN,B.ahr,!1)
B.aqX=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.bjH=new A.a6(B.cC,B.aqX,!1)
B.akz=s([B.awN,B.bjf,B.bkA,B.blU,B.bjH],t.a)
B.bni=new A.cl("story_05_old_oak",B.akz)
B.awJ=new A.aO("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.alU=s(["\u201eCo se to stalo?\u201c"],t.s)
B.blx=new A.a6(B.bN,B.alU,!1)
B.ahe=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.bjF=new A.a6(B.cC,B.ahe,!1)
B.aeb=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.bjD=new A.a6(B.bN,B.aeb,!1)
B.ai7=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.bkN=new A.a6(B.cC,B.ai7,!1)
B.awp=new A.aO("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.ahv=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.bku=new A.a6(B.cK,B.ahv,!1)
B.aqC=s([B.awJ,B.blx,B.bjF,B.bjD,B.bkN,B.awp,B.bku],t.a)
B.bmD=new A.cl("story_06_waterfall_chest",B.aqC)
B.ax1=new A.aO("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.afE=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.blW=new A.a6(B.cK,B.afE,!1)
B.aqv=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.bjG=new A.a6(B.cC,B.aqv,!1)
B.axv=new A.aO("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.aqK=s([B.ax1,B.blW,B.bjG,B.axv],t.a)
B.bmZ=new A.cl("story_07_scroll",B.aqK)
B.aw3=new A.aO("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.aow=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.blK=new A.a6(B.bN,B.aow,!1)
B.amE=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.bip=new A.a6(B.cK,B.amE,!1)
B.aen=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.bix=new A.a6(B.bN,B.aen,!1)
B.aiM=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.bjg=new A.a6(B.cK,B.aiM,!1)
B.ajM=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.blt=new A.a6(B.cC,B.ajM,!1)
B.akA=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.bik=new A.a6(B.cK,B.akA,!1)
B.akv=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.bji=new A.a6(B.bN,B.akv,!1)
B.aht=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.bkc=new A.a6(B.cK,B.aht,!1)
B.adw=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.bj1=new A.a6(B.cC,B.adw,!1)
B.ad1=s([B.aw3,B.blK,B.bip,B.bix,B.bjg,B.blt,B.bik,B.bji,B.bkc,B.bj1],t.a)
B.bmK=new A.cl("story_08_ending_dialogue",B.ad1)
B.akJ=s([B.bn6,B.bmH,B.bmA,B.bmz,B.bmC,B.bmw,B.bni,B.bmD,B.bmZ,B.bmK],t.WD)
